package com.rikkeibank.transaction.service;import com.rikkeibank.common.api.BusinessException;import com.rikkeibank.common.events.TransferEvent;import com.rikkeibank.transaction.domain.BankTransaction;import com.rikkeibank.transaction.repo.TransactionRepository;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.Instant;import java.util.UUID;
@Service public class TransferSagaService{private static final Logger log=LoggerFactory.getLogger(TransferSagaService.class);private final TransactionRepository repo;private final AccountOperations accounts;private final KafkaTemplate<String,TransferEvent> kafka;private final boolean failureInjection;public TransferSagaService(TransactionRepository r,AccountOperations a,KafkaTemplate<String,TransferEvent> k,@Value("${demo.failure-injection-enabled:false}")boolean f){repo=r;accounts=a;kafka=k;failureInjection=f;}
 @Transactional public BankTransaction transfer(UUID source,UUID target,UUID customer,BigDecimal raw,boolean simulate){if(source.equals(target))throw BusinessException.badRequest("SAME_ACCOUNT","Source and target must differ");BigDecimal amount=raw.setScale(2,RoundingMode.HALF_EVEN);if(amount.signum()<=0)throw BusinessException.badRequest("INVALID_AMOUNT","Amount must be positive");BankTransaction tx=repo.save(new BankTransaction(source,target,customer,amount));boolean debited=false;try{accounts.debit(tx.getId(),source,customer,amount);debited=true;tx.debited();publish(tx,"DEBITED",null);if(simulate&&failureInjection)throw new IllegalStateException("Demo credit failure");accounts.credit(tx.getId(),target,customer,amount);tx.complete();publish(tx,"COMPLETED",null);return tx;}catch(Exception failure){boolean compensated=false;if(debited){try{accounts.refund(tx.getId(),source,customer,amount);compensated=true;}catch(Exception compensationFailure){log.error("CRITICAL: compensation failed for transfer {}",tx.getId(),compensationFailure);}}tx.fail(safe(failure),compensated);publish(tx,compensated?"COMPENSATED":"FAILED",safe(failure));return tx;}}
 private void publish(BankTransaction tx,String status,String reason){TransferEvent e=new TransferEvent(tx.getId(),tx.getSourceAccountId(),tx.getTargetAccountId(),tx.getCustomerId(),tx.getAmount(),status,reason,Instant.now());kafka.send("bank.transfer.events",tx.getId().toString(),e).whenComplete((r,x)->{if(x!=null)log.error("Kafka publish failed for {}",tx.getId(),x);});}private String safe(Exception e){String m=e.getMessage();return (m==null?e.getClass().getSimpleName():m).substring(0,Math.min(m==null?e.getClass().getSimpleName().length():m.length(),500));}}
